INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','easy','mcq','From which organ does haematopoiesis predominantly originate in adults?','["Red bone marrow of flat bones and proximal long bones", "Yellow bone marrow of long bone shafts", "Liver and spleen", "Lymph nodes and thymus"]','A','In adults, haematopoiesis occurs mainly in red bone marrow of flat bones (sternum, ribs, vertebrae, pelvis) and proximal ends of long bones. Yellow marrow is inactive fatty marrow; liver and spleen are primary sites only during fetal life.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','hard','mcq','Which cellular mechanism explains why G-CSF primarily raises the neutrophil count rather than the erythrocyte count?','["G-CSF acts on committed myeloid (granulocyte-monocyte) progenitors not on erythroid-committed progenitors", "G-CSF acts on pluripotential stem cells which always produce neutrophils", "G-CSF destroys erythroid progenitors preventing erythrocyte increase", "G-CSF has equal effects on all lineages but neutrophils mature faster"]','A','G-CSF acts on committed granulocyte-monocyte progenitors and on later neutrophil precursors, not on erythroid-committed progenitors (which are driven by EPO). This lineage commitment explains the lineage specificity of haematopoietic growth factors.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','easy','mcq','Which growth factor is the principal stimulator of erythropoiesis?','["Granulocyte colony-stimulating factor (G-CSF)", "Erythropoietin (EPO)", "Thrombopoietin (TPO)", "Interleukin-5 (IL-5)"]','B','Erythropoietin (EPO), produced mainly by the kidneys (~90%) in response to tissue hypoxia, is the primary regulator of red blood cell production. G-CSF drives neutrophil production, TPO drives platelet production, and IL-5 supports eosinophil differentiation.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','medium','mcq','Differentiation inducers in haematopoiesis act primarily on which type of cell?','["Mature circulating blood cells", "Committed (unipotential) stem cells", "Pluripotential stem cells only", "Endothelial progenitor cells"]','B','Differentiation inducers act on committed (unipotential) stem cells to cause them to differentiate along specific cell lineages. Proliferation inducers such as stem cell factor act on pluripotential stem cells; mature circulating cells cannot de-differentiate.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','hard','mcq','A patient with chronic renal failure presents with normocytic anaemia. The most likely underlying mechanism is:','["Decreased transferrin production by the liver", "Impaired EPO secretion by peritubular renal cells", "Increased red cell destruction by the spleen", "Deficiency of vitamin B12 due to poor absorption"]','B','Approximately 90% of EPO is produced by peritubular interstitial cells of the kidney. In chronic renal failure, these cells are destroyed or dysfunctional, leading to inadequate EPO production and therefore reduced erythropoiesis causing normocytic anaemia.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','easy','mcq','In the fetus, which organ is the primary site of haematopoiesis during the middle trimester?','["Bone marrow", "Lymph nodes", "Liver", "Thymus"]','C','During the middle trimester of fetal development, the liver is the dominant haematopoietic organ. The yolk sac is active very early in gestation, and bone marrow gradually takes over from about 5 months, becoming the sole site in postnatal life.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','medium','mcq','Which of the following statements about adult bone marrow haematopoiesis is CORRECT?','["All bones are actively haematopoietic throughout adult life", "Active red marrow cannot revert to yellow marrow once converted", "Yellow marrow can revert to active red marrow if haematopoietic demand increases", "Lymphoid cells are produced only in lymph nodes"]','C','Yellow (inactive) marrow can revert to haematopoietically active red marrow in conditions of increased demand, such as severe haemolytic anaemia or myelofibrosis. The liver and spleen can also resume haematopoiesis (extramedullary haematopoiesis) in extreme cases.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','medium','mcq','Which single cell type gives rise to all blood cell lineages?','["Myeloblast", "Lymphoblast", "Pluripotential haematopoietic stem cell", "Colony-forming unit-erythrocyte (CFU-E)"]','C','The pluripotential haematopoietic stem cell (haemocytoblast) is the common ancestor for all blood cell types. CFU-E is a committed erythroid progenitor; myeloblasts and lymphoblasts are further downstream committed progenitors.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','medium','mcq','At what age does the long-bone shaft (diaphyseal) marrow normally cease to produce red blood cells?','["5 years", "10 years", "25 years", "20 years"]','D','According to Guyton and Hall, the diaphyseal marrow of long bones stops producing red blood cells by approximately age 20. Before age 5, essentially all bone marrow is active; between 5 and 20, the diaphyses progressively convert to inactive yellow (fatty) marrow.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haematopoiesis','medium','mcq','Approximately 90% of erythropoietin (EPO) is produced by which cell type?','["Kupffer cells of the liver", "Bone marrow stromal cells", "Splenic red pulp macrophages", "Peritubular interstitial cells of the kidney"]','D','Approximately 90% of EPO is produced by peritubular interstitial (fibroblast-like) cells of the kidney in response to reduced tissue oxygen tension. The liver contributes the remaining ~10% and becomes relatively more important when renal EPO production fails.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','easy','mcq','From which committed progenitor do red blood cells differentiate in the bone marrow?','["Colony-forming unit-erythrocyte (CFU-E)", "Myeloblast", "Megakaryoblast", "Common lymphoid progenitor"]','A','CFU-E (colony-forming unit-erythrocyte) is the committed erythroid progenitor that differentiates under EPO stimulation through proerythroblast, basophil erythroblast, polychromatic erythroblast, orthochromatic erythroblast, reticulocyte, and finally mature erythrocyte stages.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','easy','mcq','Which shape best describes normal red blood cells and facilitates gas exchange?','["Biconcave disc thicker at the periphery than the centre", "Spherical with uniform thickness", "Cylindrical with rounded ends", "Biconcave disc thicker at the centre than the periphery"]','A','Normal RBCs are biconcave discs that are thicker at the periphery (2.5 um) and thinner at the centre (1 um). This maximises surface-area-to-volume ratio, facilitating rapid O2 and CO2 diffusion and allowing deformation while passing through narrow capillaries.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','medium','mcq','What is the normal lifespan of a mature red blood cell in the circulation?','["120 days", "60 days", "30 days", "200 days"]','A','The normal lifespan of a red blood cell is approximately 120 days, after which its metabolic systems become too degenerated to sustain it, and it is phagocytosed mainly by macrophages in the spleen, liver, and bone marrow.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','medium','mcq','Which enzyme within red blood cells catalyses the conversion of CO2 and water to carbonic acid?','["Superoxide dismutase", "Carbonic anhydrase", "Lactate dehydrogenase", "Glucose-6-phosphate dehydrogenase"]','B','Carbonic anhydrase within RBCs catalyses the reversible reaction CO2 + H2O producing H2CO3 at a rate thousands of times faster than the uncatalysed reaction, enabling the blood to carry large amounts of CO2 as bicarbonate from tissues to the lungs.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','hard','mcq','A patient has a haematocrit of 55% with elevated EPO levels. Which condition is MOST consistent?','["Iron deficiency anaemia", "Secondary polycythaemia due to chronic hypoxia", "Polycythaemia vera (primary polycythaemia)", "Thalassaemia minor"]','B','Elevated EPO with high haematocrit indicates secondary polycythaemia, most commonly caused by chronic hypoxia (e.g., high altitude, COPD). In polycythaemia vera, EPO is suppressed because erythroid proliferation is autonomous and EPO-independent.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','medium','mcq','What is the normal haemoglobin concentration in the blood of an adult man?','["8-10 g/dl", "12-14 g/dl", "15-16 g/dl", "18-20 g/dl"]','C','The normal haemoglobin concentration is approximately 15-16 g/dl in adult males (and about 14 g/dl in adult females). Values below 13.5 g/dl in men are generally considered anaemic.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','medium','mcq','What is the maximum concentration of haemoglobin achievable inside a red blood cell?','["20 g/100 ml of cells", "28 g/100 ml of cells", "34 g/100 ml of cells", "45 g/100 ml of cells"]','C','RBCs can concentrate haemoglobin up to about 34 g/100 ml of cell volume. This value does not rise further because it represents the metabolic limit of the cell''''s haemoglobin-forming mechanism.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','easy','mcq','Where are aged, damaged red blood cells primarily destroyed in the body?','["Kidneys and lungs", "Liver sinusoids alone", "Neutrophils in peripheral blood", "Macrophages of the spleen, liver, and bone marrow"]','D','Aged RBCs undergo phagocytosis primarily by tissue macrophages in the spleen, liver (Kupffer cells), and bone marrow. Many RBCs also self-destruct mechanically in the spleen as they squeeze through the red pulp sinusoids. The kidneys and lungs do not play a significant role.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','medium','mcq','What is the normal mean diameter of a human red blood cell?','["2.8 micrometres", "5.0 micrometres", "12.0 micrometres", "7.8 micrometres"]','D','Normal RBCs are biconcave discs with a mean diameter of about 7.8 micrometres and a thickness of 2.5 micrometres at the thickest point and 1 micrometre at the centre. This shape greatly increases the surface-area-to-volume ratio for gas exchange.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Red Blood Cell Physiology','hard','mcq','Which vitamin is specifically required for normal maturation of red blood cell precursors, and what anaemia results from its deficiency?','["Vitamin C, causing haemolytic anaemia", "Vitamin A, causing microcytic anaemia", "Vitamin E, causing aplastic anaemia", "Vitamin B12 (cobalamin), causing megaloblastic anaemia"]','D','Vitamin B12 (cobalamin) and folic acid are both essential for DNA synthesis and hence normal nuclear maturation of red cell precursors. Deficiency of either causes megaloblastic anaemia with large, poorly functioning erythrocytes.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','easy','mcq','Which part of the haemoglobin molecule directly binds oxygen?','["The haem group containing iron (Fe2+)", "The globin protein chains alone", "The porphyrin ring without iron", "The 2,3-DPG binding site between beta chains"]','A','Oxygen binds reversibly to the iron atom (Fe2+) within the haem group of haemoglobin. Each haemoglobin molecule has four haem groups and can therefore bind four oxygen molecules. The globin chains determine affinity characteristics but do not directly bind O2.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','hard','mcq','Which of the following physiological changes would shift the oxygen-haemoglobin dissociation curve to the LEFT?','["Alkalosis with elevated blood pH", "Elevated body temperature during fever", "Metabolic acidosis with decreased blood pH", "Increased 2,3-DPG production during chronic anaemia"]','A','A left shift of the oxyhaemoglobin dissociation curve (increased O2 affinity) is caused by alkalosis (high pH), decreased temperature, and decreased 2,3-DPG. This is the opposite of the Bohr effect. A left shift impairs O2 release to tissues but occurs physiologically in the lungs.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','easy','mcq','Adult haemoglobin A (HbA) consists of which combination of globin chains?','["Two alpha chains and two gamma chains", "Two alpha chains and two beta chains", "Two beta chains and two delta chains", "Four alpha chains"]','B','HbA, the predominant haemoglobin in adults (~97% of total), is made of two alpha and two beta globin chains. HbA2 has two alpha and two delta chains (~2.5%), and HbF has two alpha and two gamma chains (fetal haemoglobin).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','medium','mcq','Foetal haemoglobin (HbF) has a higher oxygen affinity than adult HbA. What is the primary structural basis for this?','["HbF contains four alpha chains instead of two", "HbF has gamma chains in place of beta chains, which bind 2,3-DPG less avidly", "HbF has a larger molecular weight", "HbF contains haem with a different iron oxidation state"]','B','HbF (alpha2gamma2) has gamma chains instead of beta chains. Gamma chains bind 2,3-diphosphoglycerate (2,3-DPG) less avidly than beta chains, so HbF remains more in the relaxed (R) state and has a higher O2 affinity. This facilitates oxygen transfer from maternal HbA to fetal HbF across the placenta.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','medium','mcq','Which statement correctly describes the Haldane effect?','["The Bohr effect and the Haldane effect describe the same phenomenon", "Deoxygenated haemoglobin carries more CO2 than oxygenated haemoglobin at the same PCO2", "Oxygenated blood carries more CO2 than deoxygenated blood for the same PCO2", "CO2 has no effect on haemoglobin structure"]','B','The Haldane effect states that deoxygenated haemoglobin (deoxyHb) can carry more CO2 than oxygenated haemoglobin (oxyHb) at the same PCO2. In tissues, O2 release promotes CO2 uptake; in lungs, O2 binding promotes CO2 release. This complements the Bohr effect.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','medium','mcq','How much oxygen can each gram of haemoglobin bind when fully saturated?','["0.5 ml O2", "1.0 ml O2", "1.34 ml O2", "2.5 ml O2"]','C','Each gram of haemoglobin can combine with 1.34 ml of oxygen at 100% saturation. With a normal haemoglobin concentration of about 15 g/dl, approximately 20 ml of O2 can be carried per 100 ml of blood.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','medium','mcq','What is the molecular weight of adult haemoglobin A (HbA)?','["16,000 daltons", "34,000 daltons", "64,458 daltons", "120,000 daltons"]','C','Haemoglobin A has a molecular weight of approximately 64,458 daltons. It consists of four haem-containing subunits (two alpha and two beta chains), each with a molecular weight of about 16,000.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','hard','mcq','In haemoglobin S (HbS), a point mutation causes which amino acid substitution in the beta-globin chain?','["Glutamic acid replaced by lysine at position 6", "Valine replaced by glutamic acid at position 6", "Glutamic acid replaced by valine at position 6", "Lysine replaced by valine at position 1"]','C','In HbS (sickle cell haemoglobin), glutamic acid (a negatively charged hydrophilic amino acid) at position 6 of the beta-globin chain is replaced by valine (a non-polar hydrophobic amino acid). Under deoxygenation, HbS polymerises into long fibres that distort the RBC into a sickle shape.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','medium','mcq','Which of the following conditions causes a RIGHT shift of the oxyhaemoglobin dissociation curve?','["Decreased temperature", "Increased pH (alkalosis)", "Decreased 2,3-DPG levels", "Increased PCO2"]','D','Increased PCO2 causes a right shift (Bohr effect), decreasing O2 affinity and promoting O2 delivery to tissues. Decreased temperature (A), increased pH (B), and decreased 2,3-DPG (C) all cause a LEFT shift, increasing O2 affinity and impairing O2 release to tissues.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Haemoglobin','hard','mcq','Methaemoglobin is clinically significant because it:','["Carries more oxygen than normal oxyhaemoglobin", "Is only found in fetal red blood cells", "Activates the coagulation cascade directly", "Contains iron in the Fe3+ state and cannot bind oxygen"]','D','Methaemoglobin contains iron in the Fe3+ (ferric) rather than Fe2+ (ferrous) state. In this oxidised state, it cannot bind molecular oxygen. Methaemoglobinaemia can be caused by drugs (e.g., dapsone, nitrates) or be congenital, and is treated with methylene blue.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','easy','mcq','Which WBC differential count percentage is normally highest in a healthy adult?','["Neutrophils (~62%)", "Lymphocytes (~30%)", "Monocytes (~5%)", "Eosinophils (~2%)"]','A','Neutrophils are the most numerous WBC type, comprising approximately 62% of the total WBC count (range 50-70%). Lymphocytes are second (~30%), with monocytes (~5%), eosinophils (~2.3%), and basophils (~0.4%) making up smaller fractions.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','medium','mcq','Which white blood cell is the first to arrive at a site of acute bacterial infection?','["Neutrophil", "Eosinophil", "Monocyte", "B lymphocyte"]','A','Neutrophils are the first responders in acute bacterial infection, arriving at the site within minutes to hours by chemotaxis. They phagocytose and destroy bacteria using lysosomes and oxidative burst. Monocytes arrive later and differentiate into macrophages.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','easy','mcq','What is the normal total white blood cell (WBC) count in an adult?','["1,000-2,000 cells/mm3", "4,000-11,000 cells/mm3", "15,000-20,000 cells/mm3", "50,000-100,000 cells/mm3"]','B','The normal adult WBC count is approximately 4,000-11,000 cells per mm3 (with Guyton citing ~7,000/mm3 as the average). Values above 11,000 generally indicate leukocytosis, while below 4,000 indicates leukopenia.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','medium','mcq','Which white blood cell type is characteristically elevated in parasitic infections and allergic responses?','["Neutrophil", "Eosinophil", "Basophil", "Monocyte"]','B','Eosinophils are elevated (eosinophilia) in parasitic infections (particularly helminth infections) and allergic/hypersensitivity disorders. Eosinophils contain major basic protein and can damage parasite membranes. Basophils are elevated in some allergic states but are far less numerous.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','hard','mcq','Approximately how many WBCs are stored in the bone marrow relative to the number circulating in blood?','["Equal numbers in marrow and blood", "About 3 times as many in marrow as in blood", "About 6 times as many in marrow as in blood", "About 50 times as many in marrow as in blood"]','B','According to Guyton and Hall, approximately three times as many WBCs are stored in the bone marrow as circulate in the blood, representing approximately a 6-day supply. This reserve can be mobilised rapidly during infection or stress.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','medium','mcq','Monocytes that migrate from the blood into tissues become which cell type?','["Plasma cells", "Mast cells", "Macrophages", "Natural killer cells"]','C','Monocytes circulate in blood for 10-20 hours, then migrate into tissues where they differentiate into macrophages. Tissue macrophages are long-lived phagocytes that process antigens, secrete cytokines, and clear cellular debris. Plasma cells are derived from B lymphocytes; mast cells arise from distinct bone marrow progenitors.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','hard','mcq','Which statement about lymphocytes in blood is CORRECT?','["Lymphocytes are produced exclusively in bone marrow and do not recirculate", "All circulating lymphocytes are B cells", "Lymphocytes produced in lymphoid tissues continually enter the circulation and recirculate via lymphatics", "Lymphocytes have a lifespan of only 24 hours"]','C','Lymphocytes are produced in lymphoid tissues (lymph nodes, spleen, thymus, tonsils, MALT) and continually enter the circulation via lymphatics. They pass out of the blood into tissues, re-enter lymph, and return to blood in a continuous recirculation cycle. Life spans range from days to years.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','medium','mcq','Which white blood cell contains granules rich in histamine and heparin?','["Neutrophil", "Eosinophil", "Lymphocyte", "Basophil"]','D','Basophils (and their tissue counterpart, mast cells) contain large granules packed with histamine and heparin. In IgE-mediated hypersensitivity reactions, antigen cross-linking of IgE on basophil/mast cell surfaces triggers degranulation and histamine release, causing allergic symptoms.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','medium','mcq','Which of the following WBCs is derived from the lymphoid stem cell lineage?','["Neutrophil", "Eosinophil", "Monocyte", "T lymphocyte"]','D','T lymphocytes (and B lymphocytes) are derived from the lymphoid stem cell lineage. Neutrophils, eosinophils, basophils, and monocytes are all derived from the myeloid (granulocyte-monocyte) lineage originating from the myeloid committed stem cell.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','White Blood Cell Physiology','hard','mcq','A patient develops agranulocytosis after taking carbimazole. Which of the following would you expect?','["Increased susceptibility to viral infection only", "Increased platelet count compensating for the lost granulocytes", "Increased lymphocyte count with no clinical consequence", "Markedly increased risk of bacterial and fungal infections due to absence of neutrophils"]','D','Agranulocytosis is characterised by a severe reduction in granulocytes, particularly neutrophils. Without neutrophils, the body''''s primary defence against bacteria and fungi is impaired, leading to life-threatening infections. Lymphocytes handle viral and adaptive immune responses, not primary bacterial defence.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','easy','mcq','What is the normal lifespan of a platelet in the circulation?','["7-10 days", "1-2 days", "30 days", "120 days"]','A','Platelets survive in the circulation for approximately 7-10 days before being removed by macrophages, primarily in the spleen. Unlike RBCs (120 days), platelets are short-lived anucleate cell fragments.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','medium','mcq','Which glycoprotein receptor on the platelet surface mediates adhesion to von Willebrand factor (vWF) at sites of vascular injury?','["GPIb-IX-V", "GPIIb/IIIa (alphaIIbbeta3)", "P-selectin", "GP VI"]','A','GPIb-IX-V is the platelet receptor that binds von Willebrand factor (vWF) adhered to exposed subendothelial collagen, mediating initial platelet tethering and adhesion especially at high shear rates. GPIIb/IIIa mediates platelet aggregation by binding fibrinogen and vWF after activation.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','medium','mcq','Which haematopoietic growth factor is most important for megakaryocyte proliferation and platelet production?','["Thrombopoietin (TPO)", "G-CSF (granulocyte colony-stimulating factor)", "Erythropoietin (EPO)", "Stem cell factor (SCF)"]','A','Thrombopoietin (TPO), produced mainly by the liver, is the primary regulator of megakaryocyte maturation and platelet production. EPO drives erythropoiesis, G-CSF acts on neutrophil progenitors, and SCF acts on pluripotential stem cells.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','medium','mcq','Which substance released by activated platelets is the most potent amplifier of platelet aggregation?','["Prostacyclin (PGI2)", "Thromboxane A2 (TXA2)", "Nitric oxide (NO)", "Heparin"]','B','Thromboxane A2 (TXA2), synthesised from arachidonic acid by activated platelets via COX-1, is a potent vasoconstrictor and amplifier of platelet aggregation. Prostacyclin (PGI2) and nitric oxide are produced by endothelium and inhibit platelet aggregation.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','hard','mcq','GPIIb/IIIa (alphaIIbbeta3 integrin) is the receptor responsible for which step of primary haemostasis?','["Platelet adhesion to subendothelial collagen", "Platelet aggregation by binding fibrinogen and vWF", "Release of ADP from dense granules", "Vasoconstriction of small arteries"]','B','GPIIb/IIIa, after platelet activation causes a conformational change, binds fibrinogen (and vWF) to cross-link platelets and form the primary platelet plug. Drugs like abciximab, eptifibatide, and tirofiban block this receptor to prevent aggregation.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','easy','mcq','Platelets are formed by fragmentation of which bone marrow cell?','["Proerythroblast", "Myeloblast", "Megakaryocyte", "Monoblast"]','C','Platelets (thrombocytes) are small anucleate fragments shed from large polyploid megakaryocytes in the bone marrow. Each megakaryocyte can produce thousands of platelets before its cytoplasm is fully consumed.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','medium','mcq','Which of the following is NOT a component released from platelet alpha-granules?','["Fibrinogen", "vWF (von Willebrand factor)", "ADP and serotonin", "Platelet factor 4 (PF4)"]','C','ADP and serotonin are stored in and released from dense granules (delta-granules), not alpha-granules. Alpha-granules contain fibrinogen, vWF, platelet factor 4 (PF4), P-selectin, and various growth factors. Dense granules also contain calcium and ATP.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','hard','mcq','Aspirin reduces platelet aggregation by which mechanism?','["Blocking GPIIb/IIIa receptors irreversibly", "Increasing platelet cAMP levels", "Irreversibly inhibiting COX-1, reducing TXA2 synthesis", "Blocking ADP receptors (P2Y12) on platelets"]','C','Aspirin irreversibly acetylates and inhibits COX-1 (cyclooxygenase-1) in platelets, preventing synthesis of TXA2. Because platelets are anucleate and cannot regenerate COX-1, aspirin''''s effect lasts the entire platelet lifespan (~7-10 days). Clopidogrel blocks ADP receptors (P2Y12); abciximab blocks GPIIb/IIIa.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','medium','mcq','What is the normal platelet count in peripheral blood?','["10,000-50,000 per mm3", "500,000-750,000 per mm3", "1,000,000-2,000,000 per mm3", "150,000-400,000 per mm3"]','D','The normal platelet count ranges from approximately 150,000 to 400,000 per mm3, with an average of about 300,000/mm3. Thrombocytopenia is defined as below 150,000/mm3; thrombocytosis as above 400,000/mm3.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Platelet Physiology','hard','mcq','A patient with Glanzmann thrombasthenia has a deficiency of GPIIb/IIIa. Which finding would you expect?','["Prolonged PT with normal APTT", "Thrombocytopenia with splenomegaly", "Normal bleeding time with abnormal coagulation studies", "Normal platelet count with prolonged bleeding time and absent platelet aggregation"]','D','Glanzmann thrombasthenia is characterised by absence or dysfunction of GPIIb/IIIa, leading to failure of platelet aggregation. Platelet count is normal, but the bleeding time is prolonged, and platelet aggregation studies show absent response to agonists. PT and APTT are normal.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','easy','mcq','The extrinsic pathway of coagulation is initiated by release of tissue factor (TF). Which factor does TF bind to initiate the cascade?','["Factor VII", "Factor VIII", "Factor X", "Factor XII"]','A','Tissue factor (TF, factor III), expressed on the surface of damaged subendothelial cells, binds and activates circulating factor VII to form the TF-VIIa complex. This complex then activates factor X (extrinsic Xase) and factor IX to propagate coagulation.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','medium','mcq','What is the final product of the coagulation cascade that forms the structural meshwork of a blood clot?','["Cross-linked fibrin", "Prothrombin", "Thrombin", "Fibrinogen"]','A','Thrombin cleaves fibrinogen to fibrin monomers, which polymerise into fibrin fibers. Factor XIII (fibrin stabilising factor), activated by thrombin, then cross-links adjacent fibrin fibers, creating a strong, stable clot meshwork.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','hard','mcq','Which clotting factor is deficient in haemophilia A, and what is the inheritance pattern?','["Factor VIII, X-linked recessive", "Factor IX, autosomal recessive", "Factor VII, autosomal dominant", "Factor XI, X-linked dominant"]','A','Haemophilia A is caused by a deficiency of factor VIII (antihemophilic factor A). It is X-linked recessive and presents with prolonged APTT, normal PT, and bleeding into joints (haemarthroses) and muscles. Haemophilia B is factor IX deficiency; haemophilia C is factor XI deficiency.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','easy','mcq','Fibrinogen is produced by which organ?','["Spleen", "Liver", "Kidney", "Bone marrow"]','B','Fibrinogen, like most coagulation factors, is produced by the liver. Liver disease significantly decreases fibrinogen production, contributing to coagulopathy in cirrhosis. Normal plasma fibrinogen concentration is 100-700 mg/dl.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','medium','mcq','Which vitamin K-dependent clotting factors are produced by the liver?','["I, II, V, VIII", "II, VII, IX, X", "VIII, IX, XI, XII", "I, III, V, VII"]','B','Vitamin K is required for the hepatic synthesis of clotting factors II (prothrombin), VII, IX, and X. Vitamin K enables gamma-carboxylation of glutamate residues needed for calcium binding and activation. Protein C and S are also vitamin K-dependent.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','medium','mcq','What is the role of factor XIII in the coagulation cascade?','["It activates prothrombin to thrombin", "It converts fibrinogen to fibrin monomers", "It cross-links fibrin monomers to form stable fibrin polymer", "It activates factor X in the common pathway"]','C','Factor XIII (fibrin stabilising factor), activated by thrombin, is a transglutaminase that forms covalent cross-links between fibrin monomers, creating a rigid, mechanically strong fibrin clot that resists fibrinolysis. Without it, the clot is fragile and dissolves prematurely.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','hard','mcq','A patient on warfarin therapy has a prolonged PT. This is because warfarin inhibits:','["Factor VIII and IX specifically", "Thrombin directly", "Vitamin K epoxide reductase, reducing synthesis of factors II, VII, IX, and X", "Antithrombin III, paradoxically prolonging PT"]','C','Warfarin inhibits vitamin K epoxide reductase (VKORC1), depleting the active (reduced) form of vitamin K. Without vitamin K, the liver cannot gamma-carboxylate factors II, VII, IX, X, protein C, and protein S. The PT is prolonged first because factor VII has the shortest half-life.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','medium','mcq','Calcium ions (Factor IV) are required at which steps of the coagulation cascade?','["Only for the conversion of fibrinogen to fibrin", "Only for the intrinsic pathway", "Only for the extrinsic pathway", "Multiple steps including prothrombinase complex formation and prothrombin-to-thrombin conversion"]','D','Calcium ions (Ca2+) are required at multiple steps: the intrinsic tenase complex (IXa + VIIIa), the extrinsic Xase complex (TF + VIIa), the prothrombinase complex (Xa + Va), and for conversion of prothrombin to thrombin. EDTA chelates calcium to prevent clotting in blood tubes.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','medium','mcq','Which coagulation factor is known as the Hageman factor and initiates the intrinsic pathway?','["Factor VII", "Factor VIII", "Factor X", "Factor XII"]','D','Factor XII (Hageman factor) initiates the intrinsic (contact activation) pathway when it contacts negatively charged surfaces such as exposed collagen, glass, or kaolin. Activated factor XII (XIIa) then activates factor XI, continuing the cascade.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Coagulation Cascade','hard','mcq','The common pathway of coagulation begins with the activation of which factor?','["Factor VII", "Factor IX", "Factor XII", "Factor X"]','D','The common pathway begins with factor X activation (by either the intrinsic tenase complex or extrinsic TF-VIIa complex). Activated factor X (Xa), together with factor Va, calcium, and phospholipid, forms the prothrombinase complex that converts prothrombin (II) to thrombin (IIa).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','easy','mcq','Which of the following is the natural inhibitor of plasmin in plasma?','["Alpha-2 antiplasmin", "Protein C", "Antithrombin III", "TFPI (tissue factor pathway inhibitor)"]','A','Alpha-2 antiplasmin (alpha-2 plasmin inhibitor) is the primary physiological inhibitor of plasmin in plasma. It rapidly inactivates any free plasmin that escapes from the fibrin clot surface, limiting systemic fibrinolysis and preventing haemorrhage.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','medium','mcq','Which of the following conditions is associated with REDUCED fibrinolysis leading to thrombophilia?','["Elevated plasminogen activator inhibitor-1 (PAI-1) levels", "Deficiency of alpha-2 antiplasmin", "Excess tPA production", "Protein S excess"]','A','Elevated PAI-1 (plasminogen activator inhibitor-1) inhibits tPA and urokinase, reducing plasminogen activation and fibrinolysis. This leads to inadequate clot dissolution and thrombophilia. PAI-1 excess is found in metabolic syndrome and is a risk factor for cardiovascular thrombotic events.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','hard','mcq','Tissue factor pathway inhibitor (TFPI) inhibits coagulation by:','["Inhibiting the TF-VIIa complex and factor Xa", "Binding thrombin and removing it from circulation", "Activating protein C to degrade factor V", "Stimulating tPA release from endothelium"]','A','TFPI (tissue factor pathway inhibitor) is produced by endothelial cells and inhibits the extrinsic pathway by forming a quaternary complex with TF-VIIa and Xa, blocking further Xa generation. This makes the intrinsic pathway essential for sustained haemostasis after the initial extrinsic burst.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','easy','mcq','Which enzyme is responsible for dissolving fibrin clots in fibrinolysis?','["Thrombin", "Plasmin", "Kallikrein", "Factor Xa"]','B','Plasmin is the active enzyme of fibrinolysis. It is derived from the inactive zymogen plasminogen by the action of tissue plasminogen activator (tPA) or urokinase. Plasmin degrades fibrin into fibrin degradation products (FDPs) including D-dimers.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','medium','mcq','Protein C anticoagulant activity requires which co-factor?','["Antithrombin III", "Protein S", "Heparin", "Thrombomodulin alone is sufficient"]','B','Protein C, when activated by thrombin bound to thrombomodulin on endothelial cells, requires Protein S as a cofactor to inactivate factors Va and VIIIa. Deficiency of either Protein C or Protein S leads to increased risk of venous thromboembolism.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','easy','mcq','What is the main naturally occurring anticoagulant that neutralises thrombin and other serine proteases?','["Heparin", "Warfarin", "Antithrombin III", "Protein C"]','C','Antithrombin III (ATIII) is the most important naturally occurring anticoagulant. It neutralises thrombin, factor Xa, and other serine proteases. Heparin dramatically potentiates ATIII activity (by ~1000-fold). Deficiency of ATIII leads to hereditary thrombophilia.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','medium','mcq','Tissue plasminogen activator (tPA) is primarily produced by which cell type?','["Platelets", "Hepatocytes", "Vascular endothelial cells", "Macrophages"]','C','tPA is synthesised and released by vascular endothelial cells, primarily in response to fibrin. It converts plasminogen to plasmin most efficiently when both are bound to fibrin, confining fibrinolysis to the clot. This property is exploited in thrombolytic therapy (alteplase).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','medium','mcq','A patient presents with a positive D-dimer result. This finding specifically indicates:','["Active clot formation without any fibrinolysis", "Deficiency of plasminogen", "Fibrinolysis has occurred, meaning cross-linked fibrin has been degraded", "Elevated factor VIII levels"]','C','D-dimers are unique degradation products formed when plasmin cleaves cross-linked fibrin. A positive D-dimer indicates that fibrin was formed (clot) AND is being degraded (fibrinolysis). It is a sensitive but non-specific marker for thrombotic conditions such as DVT, PE, and DIC.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','medium','mcq','Which of the following is a synthetic antifibrinolytic agent used to reduce bleeding?','["Alteplase (tPA)", "Streptokinase", "Urokinase", "Tranexamic acid"]','D','Tranexamic acid is a lysine analogue that inhibits fibrinolysis by blocking the lysine-binding sites on plasminogen, preventing plasminogen from binding to fibrin. It is used to reduce bleeding in surgery, trauma, and menorrhagia. Alteplase, streptokinase, and urokinase are thrombolytics (pro-fibrinolytic).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Fibrinolysis & Anticoagulation','hard','mcq','Heparin exerts its anticoagulant effect primarily by:','["Directly inhibiting thrombin without any cofactor", "Inhibiting vitamin K epoxide reductase like warfarin", "Blocking GPIIb/IIIa on platelet surfaces", "Potentiating antithrombin III activity by 1000-fold, accelerating inactivation of thrombin and factor Xa"]','D','Heparin binds antithrombin III and causes a conformational change that dramatically accelerates (up to 1000-fold) ATIII''''s ability to inhibit thrombin (IIa) and factor Xa. Unfractionated heparin inhibits both IIa and Xa equally; low-molecular-weight heparins preferentially inhibit Xa.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','easy','mcq','Which blood group is considered the universal donor for red blood cell transfusions?','["Group O", "Group A", "Group AB", "Group B"]','A','Group O red blood cells lack A and B antigens (agglutinogens) on their surface, so they do not react with anti-A or anti-B antibodies in any recipient''''s plasma. This makes group O the universal donor for packed RBC transfusions. Group AB individuals are universal plasma donors.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','hard','mcq','Administration of Rh immunoglobulin (anti-D) to an Rh-negative mother after delivery of an Rh-positive baby prevents sensitisation by:','["Destroying fetal RBCs in the maternal circulation before they can stimulate antibody production", "Stimulating the mother to produce protective antibodies", "Crossing the placenta and destroying the baby''''s RBCs", "Increasing maternal platelet count to prevent haemorrhage"]','A','Anti-D immunoglobulin (RhoGAM) neutralises fetal Rh-positive RBCs that have entered the maternal circulation during delivery, preventing the mother''''s immune system from being sensitised and producing her own anti-D antibodies. It does not harm the baby as it is given post-delivery.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','easy','mcq','A person with blood group A will have which of the following in their serum?','["Anti-A antibodies", "Anti-B antibodies", "Both anti-A and anti-B antibodies", "No antibodies to ABO antigens"]','B','In the ABO system, individuals develop antibodies against the ABO antigens they lack. A person with group A has A antigens on RBCs and anti-B antibodies in serum. Group B has anti-A; Group O has both anti-A and anti-B; Group AB has neither.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','medium','mcq','Which specific Rh antigen is clinically most important and determines whether a person is Rh positive or Rh negative?','["Antigen C", "Antigen D", "Antigen E", "Antigen c"]','B','The D antigen is the most immunogenic of the Rh system antigens. Presence of the D antigen defines a person as Rh-positive (~85% of whites, ~95% of blacks); absence defines Rh-negative. Anti-D antibodies are responsible for most Rh incompatibility reactions including erythroblastosis fetalis.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','medium','mcq','Erythroblastosis fetalis (haemolytic disease of the newborn) typically occurs when:','["An Rh-positive mother carries an Rh-negative fetus", "An Rh-negative mother carries a second or subsequent Rh-positive fetus after prior sensitisation", "Both parents are Rh negative", "There is ABO incompatibility between mother and fetus with no Rh involvement"]','B','Erythroblastosis fetalis classically occurs when an Rh-negative mother has been sensitised to the Rh-D antigen (usually from a first Rh-positive pregnancy or transfusion) and subsequently carries another Rh-positive fetus. Maternal anti-D IgG crosses the placenta and destroys fetal RBCs.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','medium','mcq','In blood typing by agglutination, Type AB blood would be expected to agglutinate when mixed with:','["Anti-A serum only", "Anti-B serum only", "Both anti-A and anti-B sera", "Neither anti-A nor anti-B sera"]','C','Type AB red blood cells carry both A and B agglutinogens (antigens). Therefore, they agglutinate in the presence of anti-A antibodies AND in the presence of anti-B antibodies. Type O cells carry neither antigen and agglutinate with neither serum.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','hard','mcq','The major difference between ABO agglutinins and Rh agglutinins regarding their natural occurrence is:','["ABO agglutinins are produced only after blood transfusion, whereas Rh agglutinins develop spontaneously", "Both develop spontaneously without prior antigen exposure", "ABO agglutinins develop spontaneously, whereas Rh agglutinins require prior exposure to the Rh antigen", "Both require prior antigen exposure before antibodies form"]','C','ABO antibodies (agglutinins) develop spontaneously in individuals lacking the corresponding antigen (likely due to cross-reactivity with environmental antigens like gut bacteria). In contrast, Rh system antibodies (anti-D) almost never develop spontaneously and require prior exposure to Rh-positive blood.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','medium','mcq','In a haemolytic transfusion reaction, bilirubin levels rise because:','["The liver produces more bilirubin in response to the immune reaction", "The kidneys fail to excrete bilirubin", "Bilirubin is produced directly from the coagulation cascade", "Haemoglobin released from haemolysed red cells is converted to bilirubin by macrophages"]','D','When RBCs are haemolysed, the released haemoglobin is taken up by macrophages and converted to bilirubin via biliverdin. If more than ~400 ml is haemolysed in less than a day, the bilirubin load exceeds hepatic conjugation capacity, causing jaundice.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','medium','mcq','Which blood group is the universal recipient for red blood cell transfusions?','["Group O", "Group A", "Group B", "Group AB"]','D','Group AB individuals have both A and B antigens on their RBCs and carry neither anti-A nor anti-B antibodies in their serum, so they can receive RBCs from any ABO group without a major incompatibility reaction. They are therefore universal recipients.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Blood Groups & Transfusion','hard','mcq','A patient receives an incompatible blood transfusion. Which of the following is the most life-threatening immediate complication?','["Hypervolaemia only", "Thrombocytopenia", "Hyperkalaemia as the only complication", "Acute kidney failure due to renal vasoconstriction, haemolysis, and circulatory shock"]','D','Acute haemolytic transfusion reactions can cause acute kidney injury via: (1) renal vasoconstriction from toxic substances released during haemolysis, (2) circulatory shock from loss of functional RBCs, and (3) precipitation of haemoglobin in renal tubules. This triad can be fatal.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','easy','mcq','Which of the following factors INCREASES iron absorption from the gut?','["Vitamin C (ascorbic acid)", "Alkaline pH in the duodenum", "High dietary calcium intake", "Phytates in whole grains"]','A','Vitamin C (ascorbic acid) is a reducing agent that converts Fe3+ (poorly absorbed ferric iron) to Fe2+ (ferrous iron), the form that is absorbed via DMT-1 on enterocytes. Alkaline pH, phytates, tannins, and calcium all reduce iron absorption.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','medium','mcq','After red blood cells are destroyed by macrophages, what happens to the iron from haemoglobin?','["It is re-exported into plasma via ferroportin, bound to transferrin, and recycled for new haemoglobin synthesis", "It is excreted in urine unchanged", "It is stored permanently as haemosiderin with no further recycling", "It is converted to bilirubin along with the porphyrin ring"]','A','When RBCs are phagocytosed, macrophages degrade haemoglobin: globin is recycled to amino acids, haem is broken down with iron separated from the porphyrin ring. The iron is exported via ferroportin into plasma, binds transferrin, and is transported to erythroid precursors in bone marrow for re-use.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','hard','mcq','Which of the following mechanisms BEST explains why serum ferritin is a useful marker of total body iron stores?','["Ferritin leaks out of cells at a rate proportional to intracellular iron content", "Ferritin is produced by the kidney and its level reflects renal iron handling", "Serum ferritin is entirely derived from haemoglobin breakdown", "Ferritin is filtered and excreted by the kidneys at rates proportional to iron intake"]','A','A small proportion of ferritin (the intracellular iron storage protein) is secreted into plasma, and its serum concentration is proportional to total body iron stores. In iron deficiency, serum ferritin is typically below 12 ug/L. In iron overload, it can exceed 1000 ug/L.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','easy','mcq','Iron is primarily absorbed in which region of the gastrointestinal tract?','["Stomach", "Duodenum and upper jejunum", "Ileum", "Colon"]','B','Iron is predominantly absorbed in the duodenum and upper jejunum, where the acidic environment (from gastric acid) and the presence of reducing agents (such as vitamin C) convert Fe3+ (ferric) to Fe2+ (ferrous), which is the form absorbed by enterocytes via DMT-1.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','medium','mcq','In iron deficiency anaemia, which laboratory finding is characteristic of the blood film?','["Macrocytic (large), hyperchromic cells", "Microcytic, hypochromic cells", "Normocytic, normochromic cells with target cells", "Spherocytes and helmet cells"]','B','Iron is essential for haemoglobin synthesis. In iron deficiency, insufficient haem leads to reduced haemoglobin content per cell (hypochromia) and smaller cells (microcytosis). Macrocytic hyperchromic anaemia is seen in B12/folate deficiency; spherocytes indicate haemolysis.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','easy','mcq','What percentage of total body iron is normally present in the form of haemoglobin?','["20%", "35%", "65%", "80%"]','C','The total body iron is approximately 4-5 grams in an adult. About 65% is found in haemoglobin, ~4% in myoglobin, ~1% in cellular enzymes, and the remainder (about 30%) is stored as ferritin and haemosiderin primarily in the liver, spleen, and bone marrow.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','medium','mcq','Iron is transported in plasma bound to which protein?','["Ferritin", "Albumin", "Transferrin", "Haptoglobin"]','C','Iron is transported in the plasma loosely bound to transferrin, a beta-globulin produced by the liver. Each transferrin molecule can carry two iron atoms. Ferritin and haemosiderin are storage forms of iron; haptoglobin binds free haemoglobin.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','medium','mcq','Where is the majority of stored iron found in the body?','["In red blood cells as haemoglobin", "In the kidneys as ferritin", "In the liver, spleen, and bone marrow as ferritin and haemosiderin", "In skeletal muscle as myoglobin exclusively"]','C','Excess iron is stored primarily in the liver (hepatocytes and Kupffer cells), spleen, and bone marrow macrophages in the form of ferritin (soluble, readily mobilisable) and haemosiderin (insoluble aggregate, less readily available). Serum ferritin reflects body iron stores.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','medium','mcq','An adult man loses approximately how much iron per day through physiological routes?','["0.1 mg/day", "2.5 mg/day", "5.0 mg/day", "0.6 mg/day"]','D','According to Guyton and Hall, the average adult man loses approximately 0.6 mg of iron per day through intestinal epithelial shedding, sweat, and minor bleeding. Women lose about 1.3 mg/day on average due to additional menstrual losses. Dietary absorption must match these losses.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Iron Metabolism','hard','mcq','Hepcidin, the master regulator of iron homeostasis, reduces plasma iron levels by:','["Stimulating iron absorption in the duodenum directly", "Increasing transferrin production in the liver", "Stimulating EPO production in the kidneys", "Binding to and degrading ferroportin, blocking iron export from enterocytes and macrophages"]','D','Hepcidin, a peptide hormone produced by the liver, binds to ferroportin (the sole cellular iron export channel) on enterocytes and macrophages, causing its internalisation and degradation. This traps iron inside cells, reducing plasma iron. Elevated hepcidin in anaemia of chronic disease explains iron-restricted erythropoiesis.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','easy','mcq','Which lymphoid structure acts as a first line of immunological defence at mucosal surfaces?','["MALT (mucosa-associated lymphoid tissue)", "Thymus", "Bone marrow", "Systemic lymph nodes"]','A','MALT (mucosa-associated lymphoid tissue) includes Peyer''''s patches (gut), tonsillar tissue, bronchus-associated lymphoid tissue (BALT), and other mucosal lymphoid aggregates. It forms a distributed first-line immune defence at mucosal entry points where pathogens frequently invade.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','medium','mcq','Macrophages lining the lymph sinuses of lymph nodes primarily serve to:','["Phagocytose particulate matter and pathogens arriving in afferent lymph before they reach the bloodstream", "Produce antibodies against circulating antigens", "Produce red blood cells during infection", "Secrete erythropoietin in response to hypoxia"]','A','Macrophages lining the lymph sinuses phagocytose bacteria, cellular debris, and other particles arriving in the afferent lymph. Essentially all particulate matter is removed from lymph before it reaches the circulation, preventing systemic spread of infection.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','easy','mcq','The spleen filters which fluid compartment, making it analogous to lymph nodes filtering lymph?','["Interstitial fluid", "Blood", "Cerebrospinal fluid", "Lymph"]','B','The spleen filters blood, removing aged RBCs, cellular debris, and blood-borne pathogens via its red and white pulp. Lymph nodes, by contrast, filter lymph flowing from the tissues. The spleen is the largest secondary lymphoid organ.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','medium','mcq','A patient undergoes splenectomy for trauma. Which of the following is the most important LONG-TERM infectious risk?','["Increased susceptibility to intracellular viral infections", "Overwhelming post-splenectomy infection (OPSI) with encapsulated bacteria such as Streptococcus pneumoniae", "Increased susceptibility to helminth infections", "Severe autoimmune haemolytic anaemia"]','B','The spleen is critical for opsonisation and phagocytosis of encapsulated bacteria (S. pneumoniae, H. influenzae, N. meningitidis) that evade complement without specific antibody. After splenectomy, patients are at lifelong risk of OPSI and require vaccinations and sometimes prophylactic antibiotics.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','hard','mcq','B lymphocytes undergo primary maturation and achieve immunocompetence in which organ?','["Thymus", "Bone marrow", "Spleen", "Lymph nodes"]','B','B lymphocytes mature in the bone marrow (the mammalian equivalent of the bursa of Fabricius in birds). In the bone marrow, they undergo V(D)J recombination to generate diverse B cell receptors and are screened for self-reactivity before entering the circulation.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','easy','mcq','Lymph nodes serve all of the following functions EXCEPT:','["Filtering lymph to remove particulate matter and pathogens", "Housing lymphocytes for immune responses", "Producing red blood cells in adults", "Acting as sites of antigen presentation to T cells"]','C','Lymph nodes filter lymph, house lymphocytes and macrophages for immune responses, and present antigens. They do NOT produce red blood cells in adults - this is a function of active red bone marrow. In fetal life, the liver and spleen (not lymph nodes) have haematopoietic roles.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','medium','mcq','The red pulp of the spleen is primarily involved in:','["Presenting antigens to T lymphocytes", "Producing IgM antibodies against blood-borne antigens", "Filtering blood and removing aged or damaged red blood cells via macrophage phagocytosis", "Producing complement proteins"]','C','The splenic red pulp contains venous sinusoids and cords of Billroth lined with macrophages. RBCs passing through must squeeze through narrow sinusoidal slits; aged or abnormal RBCs that cannot deform are retained and phagocytosed. The white pulp contains lymphoid tissue for immune responses.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','medium','mcq','Which of the following lymphoid organs is classified as a PRIMARY lymphoid organ where lymphocytes develop immunocompetence?','["Spleen", "Lymph nodes", "Peyers patches", "Thymus"]','D','Primary lymphoid organs are where lymphocytes develop and achieve immunocompetence: bone marrow (B cells) and thymus (T cells). Secondary lymphoid organs - including the spleen, lymph nodes, Peyer''''s patches, and tonsils - are where mature lymphocytes encounter antigens and mount immune responses.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','medium','mcq','Which organ is responsible for the maturation and education of T lymphocytes?','["Bone marrow", "Spleen", "Lymph nodes", "Thymus"]','D','T lymphocytes mature in the thymus, where they undergo positive selection (survival if they can recognise MHC) and negative selection (deletion if they react too strongly to self-antigens). The thymus is most active in childhood and involutes with age.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Haematology','Anatomy & Physiology','Lymphoid System','hard','mcq','Which of the following correctly describes the route of lymphocyte recirculation?','["Lymphocytes enter blood from bone marrow, enter lymph nodes via afferent lymphatics, then re-enter blood via efferent lymphatics", "Lymphocytes circulate only within lymphoid organs and never enter peripheral blood", "Lymphocytes are produced in the spleen and migrate to bone marrow for recirculation", "Lymphocytes enter blood, leave blood into tissues or lymphoid organs, re-enter lymph, then drain via thoracic duct back into blood"]','D','Lymphocytes leave the blood across high endothelial venules into lymphoid tissues and peripheral tissues. They then drain into lymphatics, pass through lymph nodes, and return to blood via the thoracic duct (from the left side) and right lymphatic duct. This recirculation ensures immune surveillance throughout the body.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Guyton & Hall Medical Physiology 14th Ed');
